'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let data,driver,vehicle,terrain='Tarmac',goal='balanced',pickerKind='drivers',collectionKind='compare';
const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}};
let saved=read('garage-saved'),compare=read('garage-compare');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(x,extra='')=>x.image?`<img src="${x.image}" alt="${escapeHTML(x.name)}" ${extra}>`:'';
const ride=v=>v.ride==='Kart'?'Kart':'Bike';
const levels=(d,v)=>Object.fromEntries(data.order.map(k=>[k,Math.max(0,Math.min(25,data.driverClasses[d.class][k]+data.vehicleClasses[v.class][k]))]));
const ratio=(k,l)=>data.curves['Level'+String(l).padStart(2,'0')][k]??1;
const pair=()=>({d:driver.id,v:vehicle.id});
const same=(a,b)=>a.d===b.d&&a.v===b.v;
const resolve=p=>({d:data.drivers.find(x=>x.id===p.d),v:data.vehicles.find(x=>x.id===p.v)});
const keyStats=()=>['TopSpeed'+terrain,'Acceleration','Handling'+terrain,'DriftDashTime','Weight','InvincibleRatio'];
const label=k=>data.labels[data.order.indexOf(k)];
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function persist(){try{localStorage.setItem('garage-saved',JSON.stringify(saved));localStorage.setItem('garage-compare',JSON.stringify(compare))}catch{toast('Browser storage is unavailable. Your combos are kept for this visit.')}counts()}
function counts(){$('#savedCount').textContent=saved.length;$('#compareCount').textContent=compare.length;$('#save').textContent=saved.some(x=>same(x,pair()))?'♥  Saved combo':'♡  Save combo';$('#addCompare').textContent=compare.some(x=>same(x,pair()))?'✓ In comparison':'＋ Compare'}
function render(){
 $('#driverName').textContent=driver.character;$('#driverClass').textContent=driver.size.toUpperCase()+' · '+driver.class;$('#driverOutfit').textContent=driver.outfit;
 $('#vehicleName').textContent=vehicle.name;$('#vehicleClass').textContent=vehicle.class+' · '+ride(vehicle).toUpperCase();$('#vehicleType').textContent='Vehicle';
 $('#driverImage').src=driver.image;$('#driverImage').alt=driver.name;$('#vehicleImage').src=vehicle.image;$('#vehicleImage').alt=vehicle.name;
 const standard=vehicle.id==='Vehicle_Stk_00';$('#studio').src=standard?'assets/standard-kart-studio.webp':vehicle.image;$('#studio').alt=vehicle.name+(standard?' textured Blender studio render':' game artwork');$('#studio').classList.toggle('artwork',!standard);
 $('#renderCaption').textContent=vehicle.name.toUpperCase()+(standard?' · BLENDER STUDIO':' · GAME ARTWORK');$('#comboTitle').textContent=driver.character+' + '+vehicle.name;$('#comboClass').textContent=driver.outfit.toUpperCase()+' / '+ride(vehicle).toUpperCase();
 const ls=levels(driver,vehicle);
 $('#mainStats').innerHTML=keyStats().map(k=>`<div class="stat"><div class="stat-label"><span>${label(k)}</span><strong>${ls[k]} <small>/ 25</small></strong></div><div class="track"><div class="fill" style="width:${ls[k]*4}%"></div></div><div class="stat-ratio">×${ratio(k,ls[k]).toFixed(3)}</div></div>`).join('');
 const quickD=['Mario','Luigi','Peach','Yoshi','Bowser'].map(n=>data.drivers.find(x=>x.character===n&&x.outfit==='Standard')).filter(Boolean);
 const quickV=['Standard Kart','Baby Blooper','B Dasher','Rallygator','W-Twin Chopper'].map(n=>data.vehicles.find(x=>x.name===n)).filter(Boolean);
 $('#quickDrivers').innerHTML=quickD.map(x=>`<button class="quick ${x.character===driver.character?'active':''}" data-driver="${x.id}" title="${escapeHTML(x.name)}" aria-label="Select ${escapeHTML(x.name)}" aria-pressed="${x.id===driver.id}">${img(x)}</button>`).join('');
 $('#quickVehicles').innerHTML=quickV.map(x=>`<button class="quick ${x.id===vehicle.id?'active':''}" data-vehicle="${x.id}" title="${escapeHTML(x.name)}" aria-label="Select ${escapeHTML(x.name)}" aria-pressed="${x.id===vehicle.id}">${img(x)}</button>`).join('');
 counts();renderExtra();renderRecommendations();
 const h=new URLSearchParams({driver:driver.id,vehicle:vehicle.id});history.replaceState(null,'','#'+h);
}
function select(d,v){driver=d;vehicle=v;render()}
function renderExtra(){const ls=levels(driver,vehicle);$('#extraStats').innerHTML=`<table><caption class="muted">Full combo breakdown · ×1.000 is neutral scaling</caption><thead><tr><th>Stat</th><th>Driver points</th><th>Vehicle offset</th><th>Level / 25</th><th>Multiplier</th></tr></thead><tbody>${data.order.map(k=>`<tr><td>${label(k)}</td><td>${data.driverClasses[driver.class][k]}</td><td>${data.vehicleClasses[vehicle.class][k]>0?'+':''}${data.vehicleClasses[vehicle.class][k]}</td><td>${ls[k]}</td><td>×${ratio(k,ls[k]).toFixed(3)}</td></tr>`).join('')}</tbody></table>`}
function ranked(){const unique=new Map();data.drivers.forEach(x=>{if(!unique.has(x.character)||x.outfit==='Standard')unique.set(x.character,x)});const ds=$('#lockDriver').checked?[driver]:[...unique.values()];const stat={speed:'TopSpeed'+terrain,acceleration:'Acceleration',handling:'Handling'+terrain,turbo:'DriftDashTime'}[goal];const core=['TopSpeed'+terrain,'Acceleration','Handling'+terrain,'DriftDashTime'];let list=[];for(const d of ds)for(const v of data.vehicles){const l=levels(d,v),avg=core.reduce((a,k)=>a+l[k],0)/4;list.push({d,v,l,score:stat?l[stat]:avg,avg})}return list.sort((a,b)=>b.score-a.score||b.avg-a.avg||a.d.name.localeCompare(b.d.name)||a.v.name.localeCompare(b.v.name))}
function renderRecommendations(){let list=ranked(),seen=new Set();const picks=list.filter(x=>{const k=x.d.class+'-'+x.v.class;if(seen.has(k))return false;seen.add(k);return true}).slice(0,4);$('#recommendGrid').innerHTML=picks.map((x,i)=>`<button class="rec-card" data-rec-d="${x.d.id}" data-rec-v="${x.v.id}" aria-label="Select ${escapeHTML(x.d.name)} with ${escapeHTML(x.v.name)}"><div class="rec-top"><span>0${i+1} / ${goal==='balanced'?'ALL-ROUNDER':goal.toUpperCase()}</span><span>${Number.isInteger(x.score)?x.score:x.score.toFixed(1)} pts</span></div><div class="rec-art">${img(x.d,'loading="lazy"')}${img(x.v,'loading="lazy"')}</div><h3>${escapeHTML(x.d.character)}</h3><p>${escapeHTML(x.v.name)}</p><div class="mini-stats"><span>SPEED<b>${x.l['TopSpeed'+terrain]}</b></span><span>ACCEL.<b>${x.l.Acceleration}</b></span><span>HANDLING<b>${x.l['Handling'+terrain]}</b></span></div><span class="rec-arrow">↗</span></button>`).join('');$('#rankingNote').textContent=goal==='balanced'?'Ranked by the average of speed, acceleration, handling and mini-turbo levels. Showing distinct stat combinations.':'Ranked by '+({speed:label('TopSpeed'+terrain),acceleration:'acceleration',handling:label('Handling'+terrain),turbo:'mini-turbo duration'}[goal]).toLowerCase()+' level. Showing distinct stat combinations.'}
function openPicker(kind){pickerKind=kind;const drivers=kind==='drivers';$('#pickerTitle').textContent=drivers?'Choose your driver.':'Choose your ride.';$('#search').value='';$('#search').placeholder=drivers?'Search drivers or outfits…':'Search vehicles…';$('#search').setAttribute('aria-label',drivers?'Search drivers or outfits':'Search vehicles');$('#pickerFilter').innerHTML=drivers?'<option value="">All drivers & outfits</option><option value="standard">Standard outfits</option>'+['Small','Medium','Large'].map(s=>`<option value="${s}">${s}</option>`).join(''):'<option value="">All vehicles</option><option value="Kart">Karts</option><option value="Bike">Bikes</option>';renderPicker();$('#picker').showModal();$('#search').focus()}
function renderPicker(){const q=$('#search').value.toLowerCase(),f=$('#pickerFilter').value;const xs=data[pickerKind].filter(x=>(x.name+' '+(x.character||'')+' '+(x.outfit||'')).toLowerCase().includes(q)&&(!f||(pickerKind==='drivers'?(f==='standard'?x.outfit==='Standard':x.size===f):ride(x)===f)));$('#resultCount').textContent=xs.length+' options';$('#pickerGrid').innerHTML=xs.length?xs.map(x=>`<button class="picker-item ${x.id===(pickerKind==='drivers'?driver.id:vehicle.id)?'active':''}" data-pick="${x.id}">${img(x,'loading="lazy"')}<span>${escapeHTML(x.character||x.name)}</span><small>${escapeHTML(x.outfit||ride(x))} · ${x.class}</small></button>`).join(''):'<p class="empty">No matches. Try another search.</p>'}
function openCollection(kind){collectionKind=kind;$('#collectionTitle').textContent=kind==='saved'?'Your saved combos.':'Side by side.';renderCollection();$('#collection').showModal()}
function renderCollection(){const xs=collectionKind==='saved'?saved:compare;const pairs=xs.map(resolve).filter(x=>x.d&&x.v);$('#collectionBody').innerHTML=pairs.length?`<div class="collection-cards">${pairs.map(x=>`<article class="collection-item">${img(x.d)}${img(x.v)}<h3>${escapeHTML(x.d.name)}</h3><p>${escapeHTML(x.v.name)}</p><button class="light-button" data-load-d="${x.d.id}" data-load-v="${x.v.id}">Use combo ↗</button><button class="remove" data-remove-d="${x.d.id}" data-remove-v="${x.v.id}">Remove</button></article>`).join('')}</div>`+(collectionKind==='compare'?`<div class="comparison-scroll"><table><thead><tr><th>Stat / level</th>${pairs.map(x=>`<th>${escapeHTML(x.d.character)}<br>${escapeHTML(x.v.name)}</th>`).join('')}</tr></thead><tbody>${data.order.map(k=>{const vals=pairs.map(x=>levels(x.d,x.v)[k]),max=Math.max(...vals);return `<tr><td>${label(k)}</td>${vals.map(l=>`<td class="${l===max&&new Set(vals).size>1?'best':''}">${l} <small>· ×${ratio(k,l).toFixed(3)}</small></td>`).join('')}</tr>`}).join('')}</tbody></table></div>`:''):'<div class="empty">'+(collectionKind==='saved'?'Your favorites start here.<br>Save a combo in the garage to come back to it.':'Which ride has the edge?<br>Add up to three combos from the garage to compare their stats.')+'</div>'}
async function init(){try{const r=await fetch('data.json');if(!r.ok)throw Error('Data request failed');data=await r.json();const valid=p=>resolve(p).d&&resolve(p).v;saved=Array.isArray(saved)?saved.filter(valid):[];compare=Array.isArray(compare)?compare.filter(valid).slice(0,3):[];const hash=new URLSearchParams(location.hash.slice(1));driver=data.drivers.find(x=>x.id===hash.get('driver'))||data.drivers.find(x=>x.id==='Driver_Mario_00');vehicle=data.vehicles.find(x=>x.id===hash.get('vehicle'))||data.vehicles.find(x=>x.id==='Vehicle_Stk_00');$('#combinationCount').textContent=(data.drivers.length*data.vehicles.length).toLocaleString();render();wire()}catch(e){$('#driverName').textContent='Could not load game data';toast('Please reload to try loading the stat data again.');console.error(e)}}
function wire(){
 $('#pickDriver').onclick=$('#browseDrivers').onclick=()=>openPicker('drivers');$('#pickVehicle').onclick=$('#browseVehicles').onclick=()=>openPicker('vehicles');
 $$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
 $('#search').oninput=renderPicker;$('#pickerFilter').onchange=renderPicker;
 $('#pickerGrid').onclick=e=>{const b=e.target.closest('[data-pick]');if(!b)return;const x=data[pickerKind].find(x=>x.id===b.dataset.pick);select(pickerKind==='drivers'?x:driver,pickerKind==='vehicles'?x:vehicle);$('#picker').close()};
 $('#quickDrivers').onclick=e=>{const b=e.target.closest('[data-driver]');if(b)select(data.drivers.find(x=>x.id===b.dataset.driver),vehicle)};$('#quickVehicles').onclick=e=>{const b=e.target.closest('[data-vehicle]');if(b)select(driver,data.vehicles.find(x=>x.id===b.dataset.vehicle))};
 $$('[data-terrain]').forEach(b=>b.onclick=()=>{terrain=b.dataset.terrain;$$('[data-terrain]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});
 $$('[data-goal]').forEach(b=>b.onclick=()=>{goal=b.dataset.goal;$$('[data-goal]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderRecommendations()});$('#lockDriver').onchange=renderRecommendations;
 $('#recommendGrid').onclick=e=>{const b=e.target.closest('[data-rec-d]');if(b){select(data.drivers.find(x=>x.id===b.dataset.recD),data.vehicles.find(x=>x.id===b.dataset.recV));toast('Combo loaded into your garage')}};
 $('#random').onclick=()=>{select(data.drivers[Math.floor(Math.random()*data.drivers.length)],data.vehicles[Math.floor(Math.random()*data.vehicles.length)]);toast('A fresh combo. Give it a spin!')};
 $('#save').onclick=()=>{const p=pair(),i=saved.findIndex(x=>same(x,p));if(i>=0){saved.splice(i,1);toast('Combo removed from saved')}else{saved.push(p);toast('Saved to your garage')}persist()};
 $('#addCompare').onclick=()=>{if(compare.some(x=>same(x,pair()))){openCollection('compare');return}if(compare.length===3){toast('Three combos in comparison. Remove one to add another.');openCollection('compare');return}compare.push(pair());persist();toast('Added to comparison ('+compare.length+'/3)')};
 $('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Combo link copied')}catch{toast('Your combo is in the address bar. Copy its URL to share.')}};
 $('#allStats').onclick=()=>{const open=$('#extraStats').hidden;$('#extraStats').hidden=!open;$('#allStats').setAttribute('aria-expanded',open);$('#allStats').innerHTML=(open?'Hide full breakdown':'All 19 stats')+'<span>'+(open?'−':'＋')+'</span>'};
 $('#about').onclick=$('#dataInfo').onclick=()=>$('#methodology').showModal();
 $$('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='builder'){$('#builder').scrollIntoView({behavior:'smooth',block:'center'})}else openCollection(b.dataset.nav)});
 $('#collectionBody').onclick=e=>{let b=e.target.closest('[data-load-d]');if(b){const d=data.drivers.find(x=>x.id===b.dataset.loadD),v=data.vehicles.find(x=>x.id===b.dataset.loadV);select(d,v);$('#collection').close();toast('Combo loaded');return}b=e.target.closest('[data-remove-d]');if(b){const p={d:b.dataset.removeD,v:b.dataset.removeV};if(collectionKind==='saved')saved=saved.filter(x=>!same(x,p));else compare=compare.filter(x=>!same(x,p));persist();renderCollection()}};
}
init();
